/* @autogenerated */
import { Injectable } from '@angular/core';
import { BehaviorSubject, combineLatest, filter, map, Observable, of } from 'rxjs';
import { UserInfo } from '../identity/user-info.model';

export interface AppStateItem<T> extends Observable<T> {
  set: (value: T) => void;
}

@Injectable({
  providedIn: 'root',
})
export class AppStateService {
  public readonly language = buildWritableSignal<string>('selected-language', 'es', true);
  public readonly tenant = buildWritableSignal<string>('selected-tenant', 'main', true);
  public readonly userInfo = new ArrayOfSignals<UserInfo>('user-info-', {}, false);
  public readonly context = new ArrayOfSignals<ContextValue | null>('context-', null, true);

  public currentContext(): Observable<any> {
    const all: Observable<any>[] = [];
    Object.entries(this.context).forEach(([k, v]) => {
      all.push(
        v.pipe(
          map((val) => ({
            key: k,
            value: val?.value ?? null,
          })),
        ),
      );
    });
    return all.length == 0
      ? of({})
      : combineLatest(all).pipe(
          map((every) => {
            const result: any = {};
            every.forEach((response) => {
              result[response.key] = response.value;
            });
            return result;
          }),
        );
  }

  public fixedContext(): Observable<any> {
    const all: Observable<any>[] = [];
    Object.entries(this.context).forEach(([k, v]) => {
      all.push(
        v.pipe(
          filter((val) => val === null || !!val?.fixed),
          map((val) => ({
            key: k,
            value: val?.value,
          })),
        ),
      );
    });
    return all.length == 0
      ? of({})
      : combineLatest(all).pipe(
          map((every) => {
            const result: any = {};
            every.forEach((response) => {
              if (response.value) {
                result[response.key] = response.value;
              }
            });
            return result;
          }),
        );
  }

  public filterContext(): Observable<any> {
    const all: Observable<any>[] = [];
    Object.entries(this.context).forEach(([k, v]) => {
      all.push(
        v.pipe(
          filter((val) => val === null || !!val?.toFilter),
          map((val) => ({
            key: k,
            value: val?.value,
          })),
        ),
      );
    });
    return all.length == 0
      ? of({})
      : combineLatest(all).pipe(
          map((every) => {
            const result: any = {};
            every.forEach((response) => {
              result[response.key] = response.value;
            });
            return result;
          }),
        );
  }
}

export class ContextValue {
  private constructor(
    public readonly label: string,
    public readonly value: any,
    public readonly fixed: boolean,
    public readonly toFilter: boolean,
  ) {}

  public static null(label: string) {
    return new ContextValue(label, null, true, false);
  }

  public static default(label: string, value: any) {
    return new ContextValue(label, value, true, false);
  }

  public static fixed(label: string, value: any) {
    return new ContextValue(label, value, true, true);
  }

  public static filter(label: string, value: any) {
    return new ContextValue(label, value, false, true);
  }

  public static selection(label: string, value: any) {
    return new ContextValue(label, value, false, false);
  }
}

const stateMap = {} as any;

window.addEventListener('state-item', (event) => {
  const key = (event as any).detail.key;
  const value = (event as any).detail.value;
  if (stateMap[key]?.item) {
    stateMap[key].item.set(value);
  } else {
    stateMap[key] = { value: value };
  }
});

function buildWritableSignal<T>(name: string, def: T, persistent: boolean): AppStateItem<T> {
  const stateName = 'state-item-' + name;
  if (persistent) {
    let stored = localStorage.getItem(stateName);
    def = stored ? JSON.parse(stored).data || def : def;
  }
  const base = new BehaviorSubject<T>(def);
  const instance = base as any;
  instance.set = (value: T) => {
    // let currentValue: T = base.value;
    const current = JSON.stringify(base.value);
    const next = JSON.stringify(value);
    if (next !== current) {
      base.next(value);
      window.dispatchEvent(
        new CustomEvent('state-item', {
          detail: { key: stateName, value: value },
        }),
      );
      if (persistent) {
        localStorage.setItem(stateName, JSON.stringify({ data: value }));
      }
    }
  };
  if (stateMap[stateName] && stateMap[stateName].item) {
    console.error('The build state already was inspected');
  } else if (stateMap[stateName]) {
    base.next(stateMap[stateName].value);
    stateMap[stateName].item = base;
  } else {
    stateMap[stateName] = { item: instance, value: def };
  }
  return instance;
}

export class ArrayOfSignals<T> {
  [key: string]: AppStateItem<T>;

  private map: any = {};

  public constructor(preffix: string, def: T, persistable: boolean) {
    return new Proxy(this, {
      get: (target, prop, receiver) => {
        // Métodos “de ayuda” para iterar
        if (prop === 'entries') {
          return () => Object.entries(target.map);
        }
        if (prop === 'keys') {
          return () => Object.keys(target.map);
        }
        if (prop === Symbol.iterator) {
          // for..of: yields [key, value]
          return function* () {
            for (const key of Object.keys(target.map)) {
              yield [key, target.map[key]] as [string, AppStateItem<T>];
            }
          };
        }

        // Si es una clave string “normal”, usamos el map
        if (typeof prop === 'string') {
          if (!target.map[prop]) {
            target.map[prop] = buildWritableSignal<T>(preffix + prop, def, persistable);
          }
          return target.map[prop];
        }

        // Para el resto (símbolos, etc.), delega en el objeto original
        return Reflect.get(target, prop, receiver);
      },

      // Para que Object.keys / Object.entries vean las claves de map
      ownKeys: (target) => {
        return Reflect.ownKeys(target.map);
      },

      // Para que esas claves sean enumerables
      getOwnPropertyDescriptor: (target, prop) => {
        if (prop in target.map) {
          return {
            configurable: true,
            enumerable: true,
          };
        }
        return Reflect.getOwnPropertyDescriptor(target, prop);
      },
    }) as any;
  }
}
